// docs/tokens.json → app/src/styles/tokens.css (Tailwind v4 @theme). 결정적 생성, 손으로 고치지 않는다.
// 사용: node harness/scripts/gen-tokens.mjs
import { mkdirSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { ROOT } from "../lib/docs.mjs"
import { semanticColors, spacing, radius, textStyles, fontFamily } from "../lib/tokens.mjs"

const px = (n) => (n === 0 ? "0" : `${n}px`)
const lines = [
  "/* AUTO-GENERATED by harness/scripts/gen-tokens.mjs from docs/tokens.json — 직접 수정 금지 */",
  "@theme {",
  "  /* Tailwind 기본 팔레트·간격·글자 크기를 모두 끄고 토큰만 남긴다 */",
  "  --*: initial;",
  `  --font-sans: "${fontFamily()}", Pretendard, sans-serif;`,
  "",
  "  /* semantic 색 (primitive는 노출하지 않음) */",
  ...semanticColors().map((c) => `  --color-${c.cls}: ${c.hex};`),
  "",
  "  /* spacing: p-16 = 16px */",
  ...spacing().map((s) => `  --spacing-${s.name}: ${px(s.value)};`),
  "  /* 0은 토큰이 아니라 위치·여백 초기화용(top-0, bottom-0 등). --*: initial로 사라지므로 명시 */",
  "  --spacing-0: 0px;",
  "",
  "  /* radius: rounded-16 = 16px */",
  ...radius().map((r) => `  --radius-${r.name}: ${px(r.value)};`),
  "",
  "  /* 텍스트 스타일: text-body-medium = 16/24 Medium */",
  ...textStyles().flatMap((t) => [
    `  --text-${t.cls}: ${px(t.size)};`,
    `  --text-${t.cls}--line-height: ${px(t.lineHeight)};`,
    `  --text-${t.cls}--font-weight: ${t.weight};`,
    `  --text-${t.cls}--letter-spacing: ${t.letterSpacing}em;`,
  ]),
  "}",
  "",
]

const out = join(ROOT, "app/src/styles/tokens.css")
mkdirSync(join(ROOT, "app/src/styles"), { recursive: true })
writeFileSync(out, lines.join("\n"))
console.log(`tokens.css 생성: 색 ${semanticColors().length} · spacing ${spacing().length} · radius ${radius().length} · 텍스트 스타일 ${textStyles().length}`)
